examples.template:
MonarchGanttTimeline(
    items,
    state: $state,
    dependencies: [
        MonarchGanttTimelineDependency(id: {{dependencies.0.id}}, from: {{dependencies.0.from}}, to: {{dependencies.0.to}}),
        MonarchGanttTimelineDependency(id: {{dependencies.1.id}}, from: {{dependencies.1.from}}, to: {{dependencies.1.to}}, isConflict: {{dependencies.1.conflict}}),
        MonarchGanttTimelineDependency(id: {{dependencies.2.id}}, from: {{dependencies.2.from}}, to: {{dependencies.2.to}}, kind: {{dependencies.2.kind|case}}),
    ],
    milestones: [
        MonarchGanttTimelineMilestone(id: {{milestones.0.id}}, label: {{milestones.0.label}}, date: {{milestones.0.date|date}}),
        MonarchGanttTimelineMilestone(id: {{milestones.1.id}}, label: {{milestones.1.label}}, date: {{milestones.1.date|date}}),
    ],
    today: {{today|date}},
    onChange: { item, dates in
        guard let index = items.firstIndex(where: { $0.id == item.id }) else { return }
        items[index].start = dates.start
        items[index].end = dates.end
        // The app saves item.id with dates.start and dates.end here.
    },
    onOpen: { _ in /* The app opens the item here. */ }
)
.environment(\.calendar, Self.calendar)

examples.setupTemplate:
