    MonarchGanttTimelineItem(id: {{tasks.2.id}}, label: {{tasks.2.label}}, start: {{tasks.2.start|date}}, end: {{tasks.2.end|date}}, conflict: {{tasks.2.conflict}}),
    MonarchGanttTimelineItem(id: {{tasks.3.id}}, label: {{tasks.3.label}}, start: {{tasks.3.start|date}}, end: {{tasks.3.end|date}}, parentID: {{tasks.3.parentId}}),
    MonarchGanttTimelineItem(id: {{tasks.4.id}}, label: {{tasks.4.label}}, start: {{tasks.4.start|date}}, end: {{tasks.4.end|date}}, parentID: {{tasks.4.parentId}}),
    MonarchGanttTimelineItem(id: {{tasks.5.id}}, label: {{tasks.5.label}}, end: {{tasks.5.end|date}}, meta: {{tasks.5.meta}}),
    MonarchGanttTimelineItem(id: {{tasks.6.id}}, label: {{tasks.6.label}}),
